var e=new class{limit;waiting=[];activeCount=0;constructor(e=3){this.limit=Math.max(1,Math.floor(e))}run(e){let t=new Promise((t,n)=>{this.waiting.push({start:()=>{Promise.resolve().then(e).then(t,n).finally(()=>{--this.activeCount,this.pump()})}})});return this.pump(),t}get active(){return this.activeCount}get pending(){return this.waiting.length}pump(){for(;this.activeCount<this.limit;){let e=this.waiting.shift();if(!e)return;this.activeCount+=1,e.start()}}};async function t(e,t=2,n=750){for(let r=0;;r+=1)try{return await e()}catch(e){if(r>=t)throw e;await new Promise(e=>setTimeout(e,n*(r+1)))}}export{t as n,e as t};